"var w = $("#"+id);

function statusColor(status) {
  var colors = { proposed: 'yellow', accepted: 'green', rejected: 'red', implemented: 'blue', archived: 'grey', support: 'green', concern: 'red', question: 'orange', refine: 'blue', neutral: 'grey' };
  return colors[status] || 'grey';
}

function renderReply(reply, repliesByParent, agentMap, depth) {
  var agentId = reply.get('agent_id');
  var agent = (agentMap && agentMap[agentId]) || (agentId ? agentId.slice(0,8) : '-');
  var verdict = reply.get('verdict') || '-';
  var body = (reply.get('body') || '').replace(/\n/g, '<br>');
  var created = reply.get('created_at') ? new Date(reply.get('created_at')).toISOString().slice(0,16).replace('T',' ') : '';
  var html = '<div class="reply" style="margin-left:' + (depth * 1.5) + 'em">';
  html += '<div class="reply-meta">';
  html += '<span class="agent">' + agent + '</span>';
  html += '<span class="verdict ui tiny ' + statusColor(verdict) + ' label">' + verdict + '</span>';
  html += '<span class="created" style="color:#999;font-size:0.8em;margin-left:0.5em">' + created + '</span>';
  html += '</div>';
  html += '<div class="reply-body">' + body + '</div>';
  html += '</div>';
  var children = repliesByParent[reply.get('id')] || [];
  children.forEach(function(child) {
    html += renderReply(child, repliesByParent, agentMap, depth + 1);
  });
  return html;
}

function loadIdea(ideaId) {
  w.find('.loader').show();
  w.find('.idea-detail').hide();
  w.find('.idea-list').hide();
  w.find('.no-idea').hide();

  endpoint.schema('ai').table('idea').row('id', ideaId).then(function(idea) {
    w.find('.loader').hide();
    w.find('.idea-detail').show();

    w.find('.idea-title').text(idea.get('title'));
    var badges = '<span class="ui tiny ' + statusColor(idea.get('status')) + ' label">' + idea.get('status') + '</span>';
    if (idea.get('topic')) {
      badges += '<span class="ui tiny basic label">' + idea.get('topic') + '</span>';
    }
    w.find('.idea-badges').html(badges);
    w.find('.idea-meta').text('ID: ' + idea.get('id').slice(0,8) + '...');
    w.find('.idea-body').text(idea.get('body') || '');

    endpoint.schema('ai').table('idea_context').rows({
      where: { name: 'idea_id', op: '=', value: ideaId }
    }).then(function(contexts) {
      var ctxHtml = '';
      if (contexts.length === 0) {
        ctxHtml = '<p class="muted">No provenance links yet.</p>';
      } else {
        contexts.forEach(function(ctx) {
          var target = ctx.get('target');
          var targetStr = '-';
          if (target && typeof target === 'object') {
            targetStr = (target.schema_name || '') + '.' + (target.relation_name || '') + ' ' + (target.pk_values || []).join(', ');
          } else if (target) {
            targetStr = String(target);
          }
          ctxHtml += '<div class="context-item">';
          ctxHtml += '<span class="relationship">' + (ctx.get('relationship') || '-') + '</span>';
          ctxHtml += '<span class="target">' + targetStr + '</span>';
          if (ctx.get('excerpt')) {
            ctxHtml += '<p class="excerpt">' + ctx.get('excerpt') + '</p>';
          }
          ctxHtml += '</div>';
        });
      }
      w.find('.idea-contexts').html(ctxHtml);
    });

    Promise.all([
      endpoint.schema('ai').table('idea_reply').rows({
        where: { name: 'idea_id', op: '=', value: ideaId },
        order_by: { column: 'created_at', direction: 'asc' }
      }),
      endpoint.schema('ai').table('agent').rows({})
    ]).then(function(results) {
      var replies = results[0];
      var agents = results[1];
      var agentMap = {};
      agents.forEach(function(a) { agentMap[a.get('id')] = a.get('name'); });

      var repliesByParent = {};
      var topLevel = [];
      replies.forEach(function(r) {
        var pid = r.get('parent_reply_id');
        if (pid) {
          if (!repliesByParent[pid]) repliesByParent[pid] = [];
          repliesByParent[pid].push(r);
        } else {
          topLevel.push(r);
        }
      });
      var threadHtml = '';
      topLevel.forEach(function(r) {
        threadHtml += renderReply(r, repliesByParent, agentMap, 0);
      });
      w.find('.idea-replies').html(threadHtml || '<p class="muted">No replies yet.</p>');
    });

  }).catch(function(e) {
    w.find('.loader').hide();
    w.find('.no-idea').show();
    console.error('ai_idea error:', e);
  });
}

function loadList() {
  w.find('.loader').show();
  w.find('.idea-detail').hide();
  w.find('.no-idea').hide();

  endpoint.schema('ai').table('idea').rows({
    order_by: { column: 'created_at', direction: 'desc' }
  }).then(function(ideas) {
    w.find('.loader').hide();
    w.find('.idea-list').show();

    var listHtml = '';
    ideas.forEach(function(idea) {
      listHtml += '<div class="idea-list-item" data-id="' + idea.get('id') + '">';
      listHtml += '<span class="status ui tiny ' + statusColor(idea.get('status')) + ' label">' + idea.get('status') + '</span>';
      listHtml += '<span class="title">' + idea.get('title') + '</span>';
      if (idea.get('topic')) {
        listHtml += '<span class="topic">(' + idea.get('topic') + ')</span>';
      }
      listHtml += '</div>';
    });
    w.find('.list-container').html(listHtml);

    w.find('.idea-list-item').click(function() {
      loadIdea($(this).data('id'));
    });
  }).catch(function(e) {
    w.find('.loader').hide();
    console.error('ai_idea list error:', e);
  });
}

w.find('.back-to-list').click(function() {
  loadList();
});

var targetId = null;
if (typeof row !== 'undefined' && row && row.get) {
  targetId = row.get('id');
} else if (typeof idea_id !== 'undefined' && idea_id) {
  targetId = idea_id;
}

if (targetId) {
  loadIdea(targetId);
} else {
  loadList();
}"

